), guia AS (
    SELECT id FROM ordens_leitura WHERE slug = 'colecao-nova-marvel'
)
UPDATE itens_ordem_leitura item
SET url_capa_referencia = capa.url_capa
FROM capas capa
CROSS JOIN guia
WHERE item.ordem_leitura_id = guia.id
  AND item.posicao = capa.posicao;

