    (77, 'https://cdn.awsli.com.br/2500x2500/1703/1703064/produto/219372745/CAPIT%C3%83O%20NAUFRAGO.jpg')
), guia AS (
    SELECT id FROM ordens_leitura WHERE slug = 'colecao-nova-marvel'
)
UPDATE edicoes edicao
SET url_capa = capa.url_capa,
    data_atualizacao = CURRENT_TIMESTAMP
FROM capas capa
CROSS JOIN guia
JOIN itens_ordem_leitura item
  ON item.ordem_leitura_id = guia.id
 AND item.posicao = capa.posicao
WHERE edicao.id = item.edicao_id;

UPDATE ordens_leitura guia
SET url_capa = item.url_capa_referencia,
    data_atualizacao = CURRENT_TIMESTAMP
FROM itens_ordem_leitura item
WHERE guia.slug = 'colecao-nova-marvel'
  AND item.ordem_leitura_id = guia.id
  AND item.posicao = 1;
